  add('n2','writing','words','新的小词：大约','“这条小路大约长八十米。”为什么用“大约”？删掉后有什么变化？',{sample:'“大约”表示小路长度接近八十米，不是精确测量值。删掉后就没有表达估计的意思，和原来的信息不完全一致。',checks:['解释“大约”表示估计','联系八十米说明不是精确值','说清删去后少了估计的意思'],tip:'如果没有精确测量，怎样说才准确？'});
  add('n3','writing','compare','新的比较：送信路线','按路线和用时两个角度，比较两位送信员。',{passage:['小獾沿河岸送信，走了二十分钟。','小鹿穿过树林送信，走了十五分钟。'],sample:'路线上，小獾沿河岸走，小鹿穿过树林。时间上，小獾用了二十分钟，小鹿用了十五分钟。',checks:['两方的路线对应比较','两方的用时对应比较','没有增加原文没有的结论'],tip:'不要用“一个很慢，一个很开心”这种不同角度的说法。'});
